const b = $json.body || {};
const KNOWN = ['facebook', 'instagram', 'whatsapp'];
const errors = [];

if (!b.business_name || String(b.business_name).trim().length < 2) errors.push('business_name is required');
if (!b.brief || String(b.brief).trim().length < 15) errors.push('brief must be at least 15 characters');

const platforms = Array.isArray(b.platforms)
  ? [...new Set(b.platforms.map(p => String(p).toLowerCase()))].filter(p => KNOWN.includes(p))
  : [];
if (platforms.length === 0) errors.push('select at least one platform');

return {
  json: {
    valid: errors.length === 0,
    errors,
    input: {
      business_name: String(b.business_name || '').trim(),
      sector: String(b.sector || 'general').trim(),
      product: String(b.product || '').trim(),
      audience: String(b.audience || 'general audience').trim(),
      tone: String(b.tone || 'warm, informative').trim(),
      objective: String(b.objective || 'brand_awareness').trim(),
      brief: String(b.brief || '').trim().slice(0, 2000),
      platforms
    }
  }
};

const input = $('Code - Validate Brief').first().json.input;
const raw = $input.first().json || {};
const allowed = new Set(input.platforms);

let out = null;
const text = raw?.choices?.[0]?.message?.content;
try {
  out = JSON.parse(String(text || '').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim());
} catch (e) {
  out = null;
}

if (!out) {
  return [{
    json: {
      success: false,
      status: 'generation_failed',
      message: raw?.error?.message || 'The model did not return usable JSON. Check the OpenAI credential and try again.',
      business_name: input.business_name
    }
  }];
}

// Platform filtering is deterministic: the model never widens the platform list.
const posts = (Array.isArray(out.posts) ? out.posts : [])
  .map(p => ({
    platform: String(p.platform || '').toLowerCase(),
    caption: String(p.caption || '').trim(),
    hashtags: Array.isArray(p.hashtags) ? p.hashtags.filter(h => /^#\w/.test(String(h))) : [],
    cta: String(p.cta || '').trim()
  }))
  .filter(p => allowed.has(p.platform) && p.caption);

const missing = input.platforms.filter(p => !posts.some(x => x.platform === p));

return [{
  json: {
    success: posts.length > 0,
    status: posts.length > 0 ? 'generated' : 'generation_failed',
    campaign_id: 'demo-' + Date.now().toString(36),
    generated_at: new Date().toISOString(),
    model: $env.OPENAI_MODEL || 'gpt-4.1-mini',
    business_name: input.business_name,
    requested_platforms: input.platforms,
    missing_platforms: missing,
    intent: out.intent || null,
    strategy: out.strategy || null,
    posts,
    image_prompt: String(out.image_prompt || '').trim(),
    message: posts.length > 0 ? 'Campaign generated' : 'No usable posts were produced'
  }
}];
